def path_factor(sf: dict, constraint_id: str, source: str, sink: str):
    """SF(source) - SF(sink) for one constraint (methodology section 6).

    Congestion price at a point is -SF * mu, so a path that settles sink minus source
    is worth (SF(source) - SF(sink)) * mu. A missing shift factor is zero.
    """
    return sf.get((constraint_id, source), 0) - sf.get((constraint_id, sink), 0)

