def _network_adjustment(cons, sf, source: str, sink: str) -> Decimal:
    total = Decimal(0)
    for c in cons:
        total += network.path_factor(sf, c["constraint_id"], source, sink) * io.dec(c["shadow_price"]) \
            * io.dec(c["binding_probability"])
    return total

