def _blank(v, spec: str) -> str:
    if v is None:
        return ""
    text = format(v, spec)
    # A tiny negative residue formats as -0.00; the value is zero at this precision.
    return "0" + text[1:] if text.startswith("-0") and float(text) == 0.0 else text
